sp_widget.client_script:
api.controller = function() {
    // No client-side state needed — all rendering is driven by data.applications
};

sp_widget.css:
.aegis-tracker {
  max-width: 900px;
  margin: 0 auto;
  padding: 40px 24px 90px;

  > h2 { font-size: 1.7rem; }
  > .subtitle { color: var(--ink-soft); margin-top: 8px; font-size: 14.5px; }

  .tracker-card {
    background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius-md);
    padding: 26px 28px; margin-top: 22px;
  }
  .card-top {
    display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 10px;
    h3 { font-size: 1.1rem; margin: 0; }
    .meta { color: var(--ink-soft); font-size: 13px; margin-top: 4px; }
  }
  .stage-badge {
    font-size: 12px; font-weight: 700; padding: 6px 13px; border-radius: 999px; letter-spacing: .2px;
    &.st-active { background: var(--mustard); color: var(--forest-900); }
    &.st-done { background: #E4EEE6; color: var(--forest-700); }
  }

  .journey { display: flex; align-items: center; margin-top: 28px; }
  .j-step {
    display: flex; flex-direction: column; align-items: center; gap: 8px; flex: 0 0 auto; width: 76px;
    .circle {
      width: 32px; height: 32px; border-radius: 50%; background: var(--cream-2); color: var(--ink-soft);
      display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700;
      border: 2px solid var(--cream-2);
    }
    span { font-size: 11.5px; color: var(--ink-soft); font-weight: 600; text-align: center; }
    &.completed .circle { background: var(--forest-700); border-color: var(--forest-700); color: #fff; }
    &.active .circle { background: var(--mustard); border-color: var(--mustard); color: var(--forest-900); }
    &.completed span, &.active span { color: var(--ink); }
  }
  .j-line { flex: 1; height: 2px; background: var(--cream-2); margin-bottom: 22px; &.completed { background: var(--forest-700); } }

  .empty-state { text-align: center; padding: 60px 20px; color: var(--ink-soft); }
}

sp_widget.script:
(function() {
    data.applications = [];
    var stageStepMap = {
        'APPLIED': 1,
        'RECEIVED': 1,
        'SCREENING': 2,
        'RECRUITER_REVIEW': 2,
        'SHORTLISTED': 3,
        'INTERVIEW': 4,
        'OFFERED': 5,
        'CLOSED': 5
    };

    var userEmail = gs.getUser().getEmail();
    var gr = new GlideRecord('x_snc_aegis_application');
    if (userEmail) {
        gr.addQuery('candidate.email', userEmail);
    }
    gr.orderByDesc('sys_created_on');
    gr.setLimit(10);
    gr.query();

    while (gr.next()) {
        var stageVal = gr.getValue('stage') || 'RECEIVED';
        var stageIdx = stageStepMap[stageVal] !== undefined ? stageStepMap[stageVal] : 1;

        data.applications.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number') || gr.getUniqueValue(),
            role_title: gr.requisition ? gr.requisition.role_title.toString() : 'Software Role',
            department: gr.requisition ? gr.requisition.department.toString() : 'General',
            stage: stageVal,
            stage_idx: stageIdx
        });
    }
})();
